INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 2, "2020/07/31 12:00:00", "アヤネ", 0, "2030/12/17 14:59:59", 0, 24001, 2, 0, 24, 10046, 401, 102301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 1, "2020/07/31 12:00:00", "アヤネ", 0, "2030/12/17 14:59:59", 0, 24002, 2, 2.21, 24, 10046, 402, 102301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 2, "2020/07/31 12:00:00", "アヤネ", 0, "2030/12/17 14:59:59", 0, 24003, 2, 0, 24, 10046, 403, 102301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 2, "2020/07/31 12:00:00", "アサヒ", 0, "2030/12/17 14:59:59", 0, 24004, 1, 1.99, 24, 10046, 701, 192201);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 1, "2020/07/31 12:00:00", "アサヒ", 0, "2030/12/17 14:59:59", 0, 24005, 2, 2.21, 24, 10046, 702, 192201);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 2, "2020/07/31 12:00:00", "アサヒ", 0, "2030/12/17 14:59:59", 0, 24006, 1, 3.33, 24, 10046, 703, 192201);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 2, "2020/07/31 12:00:00", "部員３", 0, "2030/12/17 14:59:59", 0, 24007, 2, 0, 24, 10046, 801, 192301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 1, "2020/07/31 12:00:00", "部員３", 0, "2030/12/17 14:59:59", 0, 24008, 2, 2.68, 24, 10046, 802, 192301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 2, "2020/07/31 12:00:00", "部員３", 0, "2030/12/17 14:59:59", 0, 24009, 2, 0, 24, 10046, 803, 192301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("やった！", 1, "2020/07/31 12:00:00", "", 0, "2030/12/17 14:59:59", 0, 24010, 1, 0, 24, 10046, 501, 192501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("勝ったよ！", 1, "2020/07/31 12:00:00", "", 0, "2030/12/17 14:59:59", 0, 24011, 1, 0, 24, 10046, 502, 192501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい調子！", 1, "2020/07/31 12:00:00", "", 0, "2030/12/17 14:59:59", 0, 24012, 1, 0, 24, 10046, 503, 192501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 6, "2020/07/31 12:00:00", "ミサト", 0, "2030/12/17 14:59:59", 0, 24013, 2, 5.33, 24, 10046, 111, 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 1, "2020/07/31 12:00:00", "ミサト", 0, "2030/12/17 14:59:59", 0, 24014, 2, 6.85, 24, 10046, 112, 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 1, "2020/07/31 12:00:00", "ミサト", 0, "2030/12/17 14:59:59", 0, 24015, 2, 3, 24, 10046, 113, 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 1, "2020/07/31 12:00:00", "ダイチ", 0, "2030/12/17 14:59:59", 0, 24016, 2, 6.11, 24, 10046, 611, 192401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 1, "2020/07/31 12:00:00", "ダイチ", 0, "2030/12/17 14:59:59", 0, 24017, 2, 6.75, 24, 10046, 612, 192401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 2, "2020/07/31 12:00:00", "ダイチ", 0, "2030/12/17 14:59:59", 0, 24018, 2, 0, 24, 10046, 613, 192401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 2, "2020/07/31 12:00:00", "ハツネ", 0, "2030/12/17 14:59:59", 0, 24019, 1, 4.52, 24, 10046, 211, 113401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 2, "2020/07/31 12:00:00", "ハツネ", 0, "2030/12/17 14:59:59", 0, 24020, 1, 3.89, 24, 10046, 212, 113401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 1, "2020/07/31 12:00:00", "ハツネ", 0, "2030/12/17 14:59:59", 0, 24021, 2, 13.49, 24, 10046, 213, 113401);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 1, "2020/07/31 12:00:00", "カヤ", 0, "2030/12/17 14:59:59", 0, 24022, 2, 3.17, 24, 10046, 311, 106501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 1, "2020/07/31 12:00:00", "カヤ", 0, "2030/12/17 14:59:59", 0, 24023, 2, 4.42, 24, 10046, 312, 106501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 6, "2020/07/31 12:00:00", "カヤ", 0, "2030/12/17 14:59:59", 0, 24024, 1, 2.89, 24, 10046, 313, 106501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 4, "2020/07/31 12:00:00", "アヤネ", 0, "2030/12/17 14:59:59", 0, 24025, 3, 3.71, 24, 10046, 421, 102301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 2, "2020/07/31 12:00:00", "アサヒ", 0, "2030/12/17 14:59:59", 0, 24026, 1, 5.1, 24, 10046, 721, 192201);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 1, "2020/07/31 12:00:00", "部員３", 0, "2030/12/17 14:59:59", 0, 24027, 3, 4.34, 24, 10046, 821, 192301);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい勝負だったよ\nまたやろうね", 1, "2020/07/31 12:00:00", "", 0, "2030/12/17 14:59:59", 0, 24028, 1, 0, 24, 10046, 521, 192501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 1, "2020/07/31 12:00:00", "ミサト", -360, "2030/12/17 14:59:59", 0, 24029, 2, 5.62, 24, 10046, 101, 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 1, "2020/07/31 12:00:00", "ミサト", -360, "2030/12/17 14:59:59", 0, 24030, 2, 9.58, 24, 10046, 102, 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 2, "2020/07/31 12:00:00", "ミサト", -360, "2030/12/17 14:59:59", 0, 24031, 2, 0, 24, 10046, 103, 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 2, "2020/07/31 12:00:00", "ミサト", -360, "2030/12/17 14:59:59", 0, 24032, 1, 9.13, 24, 10046, 104, 113501);
INSERT INTO `v1_764a0661d321bf022e858f0a9da8c23c06e6472816701ba3f4cc59fecb50f8e0` VALUES ("絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 1, "2020/07/31 12:00:00", "ミサト", -360, "2030/12/17 14:59:59", 0, 24033, 2, 8.27, 24, 10046, 105, 113501);
